<script lang="ts">
	import { PAGE_IDS, TOTAL_PAGES } from '$lib/types';
	import { MinDiskSizeBytes } from '$lib/constants';
	import { installState, navState, isPageValid } from '$lib/store.svelte';
	import { t } from '$lib/i18n';
	// @ts-expect-error — generated by Wails
	import { RebootAndClose } from '@wails/go/gui/App.js';

	let { currentPage, onNext, onBack, onFinish }: { currentPage: number; onNext: () => void; onBack: () => void; onFinish: () => void } = $props();

	const isLastPage = $derived(currentPage === PAGE_IDS.FINISH);
	const isWelcomePage = $derived(currentPage === PAGE_IDS.WELCOME);
	const isInstallationPage = $derived(currentPage === PAGE_IDS.INSTALLATION);
	const showBack = $derived(currentPage > PAGE_IDS.WELCOME && !isLastPage && !isInstallationPage);
	const showNext = $derived(!isLastPage && !isInstallationPage);
	const showSteps = $derived(!isInstallationPage && !isLastPage);

	const steps = $derived(Array.from({ length: TOTAL_PAGES }, (_, i) => i));

	function getStepState(index: number): 'completed' | 'active' | 'pending' {
		if (index < currentPage) return 'completed';
		if (index === currentPage) return 'active';
		return 'pending';
	}

	const diskSizeOk = $derived.by(() => {
		if (!installState.disk) return false;
		const size = parseInt(installState.disk.size, 10);
		return !isNaN(size) && size >= MinDiskSizeBytes;
	});

	const nextDisabled = $derived(
		currentPage === PAGE_IDS.CONFIRMATION ? !diskSizeOk : !isPageValid(currentPage)
	);

	async function handleReboot(): Promise<void> {
		try {
			await RebootAndClose();
		} catch (err) {
			console.error('[AppFooter] Reboot failed:', err);
		}
	}
</script>

<footer class="footer">
	<div class="footer-left">
		{#if showBack}
			<button
				type="button"
				class="nav-btn nav-btn--back"
				aria-label={t('nav.back')}
				onclick={onBack}
			>
				<svg viewBox="0 0 24 24" width="24" height="24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round">
					<path d="M15 18l-6-6 6-6"/>
				</svg>
			</button>
		{/if}
	</div>
	{#if showSteps}
		<div class="footer-center">
			{#each steps as step, index}
				<div
					class={['step-dot', `step-dot--${getStepState(index)}`]}
					aria-label={`Step ${index + 1}`}
					aria-current={index === currentPage ? 'step' : undefined}
				></div>
			{/each}
		</div>
	{/if}
	<div class="footer-right">
		{#if showNext}
			<button
				type="button"
				class={['nav-btn', { 'nav-btn--disabled': nextDisabled }]}
				disabled={nextDisabled}
				aria-label={t('nav.next')}
				onclick={onNext}
			>
				<svg viewBox="0 0 24 24" width="24" height="24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round">
					<path d="M9 18l6-6-6-6"/>
				</svg>
			</button>
		{:else if isLastPage}
			<button type="button" class="btn-reboot" onclick={handleReboot}>
				{t('page.finish.reboot')}
			</button>
		{/if}
	</div>
</footer>

<style>
	.footer {
		display: flex;
		align-items: center;
		justify-content: space-between;
		padding-top: var(--spacing-lg);
	}

	.footer-left {
		display: flex;
		align-items: center;
		flex: 1;
		justify-content: flex-start;
	}

	.footer-center {
		display: flex;
		align-items: center;
		justify-content: center;
		gap: var(--spacing-sm);
		flex: 1;
	}

	.footer-right {
		display: flex;
		align-items: center;
		flex: 1;
		justify-content: flex-end;
	}

	.step-dot {
		width: 8px;
		height: 8px;
		border-radius: 50%;
		transition: all 0.2s ease;
	}

	.step-dot--pending {
		background-color: var(--color-border-light);
	}

	.step-dot--active {
		background-color: var(--color-primary);
		transform: scale(1.2);
	}

	.step-dot--completed {
		background-color: var(--color-primary);
	}

	.nav-btn {
		background: transparent;
		border: none;
		border-radius: 50%;
		aspect-ratio: 1;
		padding: 8px;
		display: flex;
		justify-content: center;
		align-items: center;
		color: var(--color-text);
		cursor: pointer;
		transition: background-color 0.15s ease, color 0.15s ease;
	}

	.nav-btn:focus-visible {
		outline: 2px solid var(--color-focus);
		outline-offset: 2px;
	}

	.nav-btn:hover:not(:disabled) {
		background-color: var(--color-bg-hover);
	}


	.nav-btn--disabled {
		opacity: 0.3;
		cursor: not-allowed;
	}

	.btn-reboot {
		font-family: inherit;
		font-weight: 600;
		font-size: var(--font-size-md);
		padding: 10px 24px;
		border-radius: var(--radius-xl);
		border: 1.5px solid var(--color-primary);
		background: transparent;
		color: var(--color-primary);
		cursor: pointer;
		transition: all 0.15s ease;
		display: inline-flex;
		align-items: center;
	}

	.btn-reboot:hover {
		background-color: var(--color-primary);
		color: var(--color-on-primary);
		border-color: var(--color-primary);
	}
</style>
